1	// Morning check-in: answering a question reveals the next one.
2	const questions = Array.from(document.querySelectorAll(".question"));
3	const answers = {};
4	
5	questions.forEach((question, index) => {
6	  question.querySelectorAll("button").forEach((button) => {
7	    button.addEventListener("click", () => {
8	      answers[question.dataset.question] = button.dataset.value;
9	      question.hidden = true;
10	      const next = questions[index + 1];
11	      if (next) {
12	        next.hidden = false;
13	      }
14	    });
15	  });
16	});
17

